def esc(s: str) -> str:
    return html.escape(str(s), quote=True)

def expanded_lesson_html(m: dict) -> str:
    """A classroom-ready delivery plan built from each chapter's authored case and lab."""
    checks = ''.join(f'<li>{esc(q)}</li>' for q in m['checks'])
    steps = ''.join(f'<li>{esc(x)}</li>' for x in m['steps'])
    return f'''<details class="delivery-plan">
      <summary>Full class plan, learner worksheet and marking guide</summary>
      <p class="small">Suggested 120-minute session. Trainers can split it into shorter meetings or extend the lab. Do not treat the time as a promised course duration.</p>
      <h4>Before learners arrive</h4>
      <ul><li>Check the linked official product guidance and note the page and date reviewed.</li>
      <li>Prepare a training organization, synthetic records and learner personas. Confirm the available edition and permissions.</li>
      <li>Rehearse the demonstration once. Keep a paper or spreadsheet version ready if a feature is unavailable.</li>
      <li>Write the business decisions that are still unknown on the board; do not silently invent them.</li></ul>
      <h4>Run the session</h4>
      <ol class="run-sheet">
        <li><strong>10 min · Start from the work.</strong> Read the Meridian case aloud. Ask learners what they need to find out before configuring anything. Separate facts, assumptions and decisions.</li>
        <li><strong>20 min · Teach the chapter ideas.</strong> Use the two “Teach the idea” paragraphs. Draw the chapter diagram. Ask learners to explain each handoff in their own words.</li>
        <li><strong>20 min · Trainer demonstration.</strong> Model the following decisions/actions while narrating why they are needed: <ol>{steps}</ol> Pause before each choice and ask the class to predict the result. Use a training account only.</li>
        <li><strong>50 min · Guided practice.</strong> Learners complete the practical task in pairs. One operates; the other records the decision, test and evidence. Switch roles halfway through. The trainer observes and asks questions instead of taking over.</li>
        <li><strong>15 min · Review evidence.</strong> Learners present the submission named above. Use these checks: <ul>{checks}</ul> Ask the learner to show the evidence, not just describe it.</li>
        <li><strong>5 min · Exit ticket.</strong> Each learner writes one decision they can now make, one assumption they still need to verify, and one failure case they tested.</li>
      </ol>
      <h4>Learner worksheet</h4>
      <div class="worksheet"><p><strong>Business need:</strong> ______________________________________________</p>
      <p><strong>Decision / design:</strong> ____________________________________________</p>
      <p><strong>Assumption or policy to confirm:</strong> _______________________________</p>
      <p><strong>Test performed and expected result:</strong> ____________________________</p>
      <p><strong>Observed result and evidence location:</strong> __________________________</p>
      <p><strong>Exception / recovery owner:</strong> ___________________________________</p>
      <p><strong>Next action:</strong> __________________________________________________</p></div>
      <h4>Independent challenge</h4>
      <p>Change one input or condition in the Meridian scenario. Explain which part of the design changes, which parts remain valid, and what new test is needed. Include this specific risk in your review: <strong>{esc(m['pitfall'])}</strong></p>
      <h4>Marking guide</h4>
      <p>Score each review check from 0 to 2: <strong>0</strong> = absent or incorrect; <strong>1</strong> = partly supported or unclear; <strong>2</strong> = correct, evidenced and repeatable by another learner. Record the check-by-check result and one next step. This is a formative chapter score; Wooplix should set any course pass threshold separately.</p>
      <h4>Trainer answer notes</h4><p>{esc(m['answer'])}</p>
      <p><strong>Common correction:</strong> {esc(m['pitfall'])}</p>
      <h4>After class</h4><p>Save the learner's evidence with the cohort materials. Ask them to explain how they would apply the same method to a different department or customer process. Update this lesson only after checking product changes and trainer experience.</p>
    </details>'''

def svg_flow(labels: list[str], number: str) -> str:
    width, height = 800, 118
    gap = 16
    n = len(labels)
    box_w = (width - 2*18 - (n-1)*gap) / n
    boxes=[]
    for i,label in enumerate(labels):
        x=18+i*(box_w+gap)
        text=esc(label)
        # Break labels on the center into two lines when they are long.
        words=label.split()
        lines=[]
        current=""
        for word in words:
            candidate=(current+" "+word).strip()
            if len(candidate)>18 and current:
                lines.append(current); current=word
            else: current=candidate
        if current: lines.append(current)
        lines=lines[:2]
        tspans="".join(f'<tspan x="{x+box_w/2:.1f}" dy="{0 if j==0 else 19}">{esc(line)}</tspan>' for j,line in enumerate(lines))
        boxes.append(f'<rect x="{x:.1f}" y="25" width="{box_w:.1f}" height="66" rx="12" fill="{["#e8f5f6","#eef2fb","#fff1ed","#eef5ed"][i%4]}" stroke="#d9e5e8"/><text x="{x+box_w/2:.1f}" y="54" text-anchor="middle" class="flowtxt">{tspans}</text>')
        if i<n-1:
            ax=x+box_w+3; bx=x+box_w+gap-3
            boxes.append(f'<path d="M{ax:.1f} 58 H{bx:.1f}" stroke="#617987" stroke-width="2" marker-end="url(#arrow{number})"/>')
    return f'<svg class="flow" viewBox="0 0 {width} {height}" role="img" aria-label="Process diagram: {esc(" then ".join(labels))}"><defs><marker id="arrow{number}" markerWidth="8" markerHeight="8" refX="7" refY="4" orient="auto"><path d="M0 0 L8 4 L0 8 Z" fill="#617987"/></marker></defs>{"".join(boxes)}</svg>'

def module_html(m: dict) -> str:
    idx=int(m["chapter"])
    check_html="".join(f'<li>{esc(q)}</li>' for q in m["checks"])
    step_html="".join(f'<li>{esc(x)}</li>' for x in m["steps"])
    ref_html="".join(f'<a class="ref-chip" href="{esc(url)}" target="_blank" rel="noopener">{esc(label)} ↗</a>' for label,url in m["refs"])
    return f'''<article class="lesson" id="m{idx:02}" data-search="{esc(m['title']+' '+m['purpose']+' '+m['teach'])}">
      <div class="lesson-top"><span class="chapter-no">{m['chapter']}</span><div><p class="eyebrow">CHAPTER {m['chapter']} · {esc(m['tag'])}</p><h2>{esc(m['title'])}</h2><p class="lede">{esc(m['purpose'])}</p></div></div>
      <div class="learn-box"><strong>By the end, learners can</strong><span>{esc(m['evidence'])}</span></div>
      <h3>Teach the idea</h3><p>{esc(m['teach'])}</p><p>{esc(m['teach2'])}</p>
      <figure class="diagram">{svg_flow(m['diagram'],m['chapter'])}<figcaption>Draw this with the class. Ask what can fail at each handoff and who owns recovery.</figcaption></figure>
      <h3>Worked example · {esc(m['case'][:70])}{'…' if len(m['case'])>70 else ''}</h3><p>{esc(m['case'])}</p>
      <div class="trainer-note"><span class="label">TRAINER WALK-THROUGH</span><ol>{step_html}</ol></div>
      <h3>Guided practical</h3><p>{esc(m['lab'])}</p><div class="evidence"><span class="label">SUBMISSION</span><p>{esc(m['evidence'])}</p></div>
      <h3>Review questions</h3><ul class="checks">{check_html}</ul>
      <details class="answer"><summary>Open trainer answer guidance</summary><p>{esc(m['answer'])}</p><p class="pitfall"><strong>Watch for:</strong> {esc(m['pitfall'])}</p></details>
      {expanded_lesson_html(m)}
      <div class="refs">{ref_html}</div>
      <label class="done"><input type="checkbox" data-progress="{idx:02}"> Mark this chapter prepared for trainer delivery</label>
    </article>'''

